export default function (wf: { setState(key: string, value: unknown): void }) {
  const jobs = ["Senior Frontend Engineer", "Frontend Platform Engineer"];
  wf.setState("source", "demo");
  console.log(`Fetched ${jobs.length} jobs`);
  return { jobs };
}

export default function (wf: {
  getState(key: string): unknown;
  getReturn(name: string): { jobs: string[] };
}) {
  console.log(`Source: ${wf.getState("source")}`);
  return { count: wf.getReturn("fetch").jobs.length };
}
